import CMigration

/// Swift equivalent of the C setjmp/longjmp control-flow mechanism.
/// Each case is thrown and caught by the appropriate executor level.
enum AWKSignal: Error {
  case break_
  case continue_
  case next
  case nextFile
  case `return`
  case exit_(Int32)
}

struct AWKRuntimeError: Error, CustomStringConvertible {
  let message: String
  var line: Int?
  init(_ msg: String, line: Int? = nil) { message = msg; self.line = line }
  var description: String {
    guard let line else { return message }
    return "\(message) at source line \(line)"
  }
}

