  // MARK: Number parsing — mirrors C's atof with leading-junk-stop behaviour.
  // C: strtod() / atof() pattern used in getfval() — tran.c
  static func parseNum(_ s: String) -> Double {
    var s = s
    while let c = s.first, c == " " || c == "\t" || c == "\n" || c == "\r" { s.removeFirst() }
    if s.isEmpty { return 0.0 }
    // Fast path
    if let d = Double(s) { return d }
    // Longest valid numeric prefix
    var i = s.startIndex
    if s[i] == "+" || s[i] == "-" { s.formIndex(after: &i) }
    var hasDot = false, hasExp = false, hasDigit = false
    while i < s.endIndex {
      let c = s[i]
      if c >= "0" && c <= "9" { hasDigit = true; s.formIndex(after: &i) }
      else if c == "." && !hasDot && !hasExp { hasDot = true; s.formIndex(after: &i) }
      else if (c == "e" || c == "E") && !hasExp && hasDigit {
        hasExp = true
        s.formIndex(after: &i)
        if i < s.endIndex && (s[i] == "+" || s[i] == "-") { s.formIndex(after: &i) }
      } else { break }
    }
    return Double(String(s[s.startIndex..<i])) ?? 0.0
  }
  
  // C: qstring() — lib.c — decodes backslash escapes in a command-line var=value
  // assignment (used for both -v and bare ARGV assignments) the same way a
  // double-quoted string constant is scanned. A bare, unescaped newline is fatal;
  // an unrecognized \X escape just drops the backslash and keeps X, matching the
  // real awk's observed behavior (verified against /usr/bin/awk).
  static func qstringDecode(_ s: String) throws -> String {
    var result = ""
    var rest = Substring(s)
    while let c = rest.first {
      rest.removeFirst()
      if c == "\n" {
        throw AWKRuntimeError("newline in string \(s.prefix(20))...")
      }
      guard c == "\\" else { result.append(c); continue }
      guard let esc = rest.first else { result.append(c); break }
      rest.removeFirst()
      switch esc {
        case "\n", "\r": break      // line continuation — skip
        case "\"": result.append("\"")
        case "n":  result.append("\n")
        case "t":  result.append("\t")
        case "f":  result.append("\u{0C}")
        case "r":  result.append("\r")
        case "b":  result.append("\u{08}")
        case "v":  result.append("\u{0B}")
        case "a":  result.append("\u{07}")
        case "\\": result.append("\\")
        case "0","1","2","3","4","5","6","7":   // octal
          var n = esc.wholeNumberValue!
          if let h = rest.first, h >= "0" && h <= "7" { n = 8 * n + h.wholeNumberValue!; rest.removeFirst() }
          if let h = rest.first, h >= "0" && h <= "7" { n = 8 * n + h.wholeNumberValue!; rest.removeFirst() }
          result.append(Character(Unicode.Scalar(UInt8(n & 0xFF))))
        default:
          result.append(esc)
      }
    }
    return result
  }

  // Number → string using printf format.  Integers use %.30g for exact output.
  // C: get_str_val() — tran.c (the CONVFMT/OFMT formatting path)
  static func numToStr(_ n: Double, fmt: String) -> String {
    guard n.isFinite else {
      return n.isNaN ? "nan" : (n > 0 ? "inf" : "-inf")
    }
    var intPart = 0.0
    if modf(n, &intPart) == 0.0 {
      return "%.30g".cFormat(n)
    }
    return fmt.cFormat(n)
  }
  
  // Returns true when the string is entirely numeric (per POSIX is_number).
  // C: is_number() — lib.c
  static func isNumber(_ s: String) -> Bool {
    let trimmed = s.trimmingCharacters(in: .whitespaces)
    guard isNumericSyntax(trimmed) else { return false }
    // one-true-awk's is_number() also rejects a syntactically valid number
    // whose magnitude overflows strtod's range (r == HUGE_VAL / errno ==
    // ERANGE) — e.g. "2e1000" is *not* a number, so it stays a plain string
    // and compares lexically rather than numerically.
    if let d = Double(trimmed), d.isInfinite { return false }
    return true
  }

  private static func isNumericSyntax(_ trimmed: String) -> Bool {
    var s = trimmed
    if s.isEmpty { return false }
    if s.first == "+" || s.first == "-" { s.removeFirst() }
    var hasDot = false, hasDigit = false
    var i = s.startIndex
    while i < s.endIndex {
      let c = s[i]
      if c >= "0" && c <= "9" { hasDigit = true }
      else if c == "." && !hasDot { hasDot = true }
      else if (c == "e" || c == "E") && hasDigit {
        s.formIndex(after: &i)
        if i < s.endIndex && (s[i] == "+" || s[i] == "-") { s.formIndex(after: &i) }
        var hasExpDigit = false
        while i < s.endIndex, s[i] >= "0" && s[i] <= "9" {
          hasExpDigit = true; s.formIndex(after: &i)
        }
        return hasExpDigit && i == s.endIndex
      } else { return false }
      s.formIndex(after: &i)
    }
    return hasDigit
  }
  
  // Compare two cells: negative / zero / positive.
  // Numeric comparison when both have numeric values; string comparison otherwise.
  // C: comparison logic in relop() — run.c
  static func compare(_ x: Cell, _ y: Cell, convfmt: String = "%.6g") -> Int {
    // FIXME: was passing convfmt
    if x.isNumber && y.isNumber {
      let xx = x.getNumber()
      let yy = y.getNumber()
      let d = xx - yy
      return d < 0 ? -1 : (d > 0 ? 1 : 0)
    }
    let xs = x.asString(fmt: convfmt), ys = y.asString(fmt: convfmt)
    return xs < ys ? -1 : (xs > ys ? 1 : 0)
  }
  
